import { iconRegistry } from "../registry.ts"
import type { IconName } from "../registry.ts"
import type { IconVariant } from "../semantics.ts"

// Static sprite generated by tooling/frontend/phosphor-sprite.ts into apps/web/public/icons/.
const spriteUrl = "/icons/phosphor.svg"

// The sprite carries regular and fill glyphs; duotone renders the regular glyph.
const variantSuffix: Record<IconVariant, string> = {
  regular: "",
  fill: "-fill",
  duotone: "",
}

export const phosphorSymbolHref = (name: IconName, variant: IconVariant): string =>
  `${spriteUrl}#ph-${iconRegistry[name]}${variantSuffix[variant]}`
